use serde::Serialize;

/// The error codes of the protocol. No other code is ever sent.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
pub enum ErrorCode {
    InvalidRequest,
    MissingParameter,
    InvalidParameterValue,
    QueueNameInvalid,
    QueueAlreadyExists,
    QueueDoesNotExist,
    ReceiptHandleInvalid,
    ReceiptHandleExpired,
    UnsupportedOperation,
    LimitExceeded,
}

/// A failed command: the code clients act on and a message for people.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct Error {
    pub code: ErrorCode,
    pub message: String,
}

impl Error {
    pub fn new(code: ErrorCode, message: impl Into<String>) -> Self {
        Self {
            code,
            message: message.into(),
        }
    }

    pub fn missing(name: &str) -> Self {
        Self::new(
            ErrorCode::MissingParameter,
            format!("{name} is required"),
        )
    }

    pub fn no_such_queue(name: &str) -> Self {
        Self::new(
            ErrorCode::QueueDoesNotExist,
            format!("queue {name:?} does not exist"),
        )
    }
}
EOF
cat > src/types.rs <<'EOF'
use serde::Serialize;

use crate::error::{Error, ErrorCode};

const FIFO_SUFFIX: &str = ".fifo";
const MAX_QUEUE_NAME_LEN: usize = 80;

/// A point on the virtual clock, in seconds since the process started.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Serialize)]
pub struct Time(u64);

impl Time {
    pub const START: Time = Time(0);

    /// Saturates: behavior past 4000000000 seconds is unspecified, and a clock
    /// that cannot go backwards is the only property callers rely on.
    pub fn plus(self, duration: Seconds) -> Time {
        Time(self.0.saturating_add(u64::from(duration.0)))
    }
}

/// A span of virtual time.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
pub struct Seconds(pub u32);

/// The name of an existing or creatable queue, checked against the naming
/// rules. Lookups by arbitrary strings go through `Borrow<str>`.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Serialize)]
pub struct QueueName(String);

impl QueueName {
    pub fn parse(name: &str) -> Result<Self, Error> {
        let stem = name.strip_suffix(FIFO_SUFFIX).unwrap_or(name);
        let valid = name.len() <= MAX_QUEUE_NAME_LEN
            && !stem.is_empty()
            && stem
                .bytes()
                .all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-');
        if valid {
            Ok(Self(name.to_owned()))
        } else {
            Err(Error::new(
                ErrorCode::QueueNameInvalid,
                format!("{name:?} is not a valid queue name"),
            ))
        }
    }

    pub fn is_fifo(&self) -> bool {
        self.0.ends_with(FIFO_SUFFIX)
    }

    pub fn as_str(&self) -> &str {
        &self.0
    }
}

impl std::borrow::Borrow<str> for QueueName {
    fn borrow(&self) -> &str {
        &self.0
    }
}
EOF
cat > src/params.rs <<'EOF'
use std::ops::RangeInclusive;

use serde_json::{Map, Value};

use crate::error::{Error, ErrorCode};
use crate::types::Seconds;

/// The members of a command object. A member whose value is `null` counts as
/// absent.
#[derive(Clone, Copy)]
pub struct Members<'a>(&'a Map<String, Value>);

impl<'a> Members<'a> {
    pub fn new(members: &'a Map<String, Value>) -> Self {
        Self(members)
    }

    pub fn optional(&self, name: &'static str) -> Option<Param<'a>> {
        self.0
            .get(name)
            .filter(|value| !value.is_null())
            .map(|value| Param { name, value })
    }

    pub fn required(&self, name: &'static str) -> Result<Param<'a>, Error> {
        self.optional(name).ok_or_else(|| Error::missing(name))
    }
}

/// One present parameter or attribute, waiting for its type check.
#[derive(Clone, Copy)]
pub struct Param<'a> {
    name: &'a str,
    value: &'a Value,
}

impl<'a> Param<'a> {
    pub fn new(name: &'a str, value: &'a Value) -> Self {
        Self { name, value }
    }

    fn invalid(&self, expected: &str) -> Error {
        Error::new(
            ErrorCode::InvalidParameterValue,
            format!("{} must be {expected}", self.name),
        )
    }

    pub fn string(self) -> Result<&'a str, Error> {
        self.value.as_str().ok_or_else(|| self.invalid("a string"))
    }

    pub fn boolean(self) -> Result<bool, Error> {
        self.value
            .as_bool()
            .ok_or_else(|| self.invalid("a boolean"))
    }

    pub fn object(self) -> Result<&'a Map<String, Value>, Error> {
        self.value
            .as_object()
            .ok_or_else(|| self.invalid("an object"))
    }

    /// An integer written without fraction or exponent, inside `range`.
    pub fn bounded<T: TryFrom<i64>>(self, range: RangeInclusive<i64>) -> Result<T, Error> {
        self.value
            .as_i64()
            .filter(|n| range.contains(n))
            .and_then(|n| T::try_from(n).ok())
            .ok_or_else(|| {
                self.invalid(&format!(
                    "an integer from {} to {}",
                    range.start(),
                    range.end()
                ))
            })
    }

    pub fn seconds(self, range: RangeInclusive<i64>) -> Result<Seconds, Error> {
        self.bounded::<u32>(range).map(Seconds)
    }
}
EOF
