        if let Some(existing) = self.queues.get(&name) {
            return if existing.config == config {
                Ok(Output::Empty {})
            } else {
                Err(Error::new(
                    ErrorCode::QueueAlreadyExists,
                    format!("queue {:?} exists with different attributes", name.as_str()),
                ))
            };
        }
