use serde::Serialize;

use crate::error::Error;
use crate::types::{QueueName, Time};

#[derive(Debug, Serialize)]
#[serde(untagged)]
pub enum Response {
    Success(Success),
    Failure(Failure),
}

impl Response {
    pub fn success(output: Output) -> Self {
        Response::Success(Success { ok: true, output })
    }

    pub fn failure(error: Error) -> Self {
        Response::Failure(Failure { ok: false, error })
    }
}

#[derive(Debug, Serialize)]
pub struct Success {
    ok: bool,
    #[serde(flatten)]
    output: Output,
}

#[derive(Debug, Serialize)]
pub struct Failure {
    ok: bool,
    error: Error,
}

/// The result members of a successful command.
#[derive(Debug, Serialize)]
#[serde(untagged)]
pub enum Output {
    Empty {},
    Now(NowOutput),
    QueueNames(QueueNamesOutput),
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "PascalCase")]
pub struct NowOutput {
    pub now: Time,
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "PascalCase")]
pub struct QueueNamesOutput {
    pub queue_names: Vec<QueueName>,
}
