mod common;

use common::{error_code, exec, session};
use serde_json::{Value, json};

fn create(name: &str, attributes: Value) -> Value {
    json!({"Command": "CreateQueue", "QueueName": name, "Attributes": attributes})
}

fn send(queue: &str, body: &str) -> Value {
    json!({"Command": "SendMessage", "QueueName": queue, "Body": body})
}

fn fifo_send(queue: &str, body: &str, group: &str, dedup: &str) -> Value {
    json!({"Command": "SendMessage", "QueueName": queue, "Body": body, "GroupId": group, "DeduplicationId": dedup})
}

fn tick(seconds: u32) -> Value {
    json!({"Command": "Tick", "Seconds": seconds})
}

#[test]
fn standard_sends_get_consecutive_ids_across_queues() {
    let responses = exec(&[
        create("a", json!({})),
        create("b", json!({})),
        send("a", "x"),
        send("b", "y"),
        send("missing", "z"),
        send("a", ""),
        send("a", "w"),
    ]);
    assert_eq!(responses[2], json!({"ok": true, "MessageId": "m-1"}));
    assert_eq!(responses[3], json!({"ok": true, "MessageId": "m-2"}));
    assert_eq!(error_code(&responses[4]), Some("QueueDoesNotExist"));
    assert_eq!(error_code(&responses[5]), Some("InvalidParameterValue"));
    assert_eq!(responses[6], json!({"ok": true, "MessageId": "m-3"}));
}

#[test]
fn send_validates_parameters_before_looking_up_the_queue() {
    let two_byte_chars_ok = "\u{e9}".repeat(512);
    let two_byte_chars_too_long = "\u{e9}".repeat(513);
    let cases: Vec<(Value, &str)> = vec![
        (json!({"Command": "SendMessage", "QueueName": "nope"}), "MissingParameter"),
        (json!({"Command": "SendMessage", "Body": "x"}), "MissingParameter"),
        (json!({"Command": "SendMessage", "QueueName": 1, "Body": null}), "MissingParameter"),
        (json!({"Command": "SendMessage", "QueueName": "nope", "Body": 5}), "InvalidParameterValue"),
        (json!({"Command": "SendMessage", "QueueName": "nope", "Body": "a".repeat(1025)}), "InvalidParameterValue"),
        (json!({"Command": "SendMessage", "QueueName": "nope", "Body": two_byte_chars_too_long}), "InvalidParameterValue"),
        (json!({"Command": "SendMessage", "QueueName": "nope", "Body": "x", "DelaySeconds": 901}), "InvalidParameterValue"),
        (json!({"Command": "SendMessage", "QueueName": "nope", "Body": "x", "GroupId": "a b"}), "InvalidParameterValue"),
        (json!({"Command": "SendMessage", "QueueName": "nope", "Body": "x", "GroupId": "a".repeat(129)}), "InvalidParameterValue"),
        (json!({"Command": "SendMessage", "QueueName": "nope", "Body": "x", "DeduplicationId": ""}), "InvalidParameterValue"),
        (json!({"Command": "SendMessage", "QueueName": "nope", "Body": "x"}), "QueueDoesNotExist"),
        (json!({"Command": "SendMessage", "QueueName": "nope", "Body": two_byte_chars_ok}), "QueueDoesNotExist"),
        (json!({"Command": "SendMessage", "QueueName": "nope", "Body": "a".repeat(1024)}), "QueueDoesNotExist"),
